package com.example.mareasv7.ui
import androidx.compose.foundation.*;import androidx.compose.foundation.layout.padding;import androidx.compose.foundation.shape.RoundedCornerShape;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.geometry.Offset;import androidx.compose.ui.graphics.*;import androidx.compose.ui.graphics.drawscope.Stroke;import androidx.compose.ui.unit.dp;import com.example.mareasv7.data.Point
@Composable fun Chart(p:List<Point>,color:Color,m:Modifier){Canvas(m.background(Panel,RoundedCornerShape(16.dp)).padding(10.dp)){if(p.size<2)return@Canvas;val lo=p.minOf{it.y};val hi=p.maxOf{it.y};val rg=(hi-lo).coerceAtLeast(.1);fun x(v:Double)=((v/24)*size.width).toFloat();fun y(v:Double)=size.height-(((v-lo)/rg)*size.height).toFloat();val path=Path();p.forEachIndexed{i,q->if(i==0)path.moveTo(x(q.x),y(q.y))else path.lineTo(x(q.x),y(q.y))};drawPath(path,color,style=Stroke(3.dp.toPx()));drawCircle(Color.White,4.dp.toPx(),Offset(0f,y(p.first().y)))}}